local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local UIModule = CS.Engine.UI.UIModule
---@type NightCatQuestComponent
local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NightCatQuestComponent)
local MournBuffDisplayRightNode = "Game.Activity.Mourn.MournBuffDisplayRightNode"

--region define
---@alias MournBuffDisplayDialog.LOCAL_CONSTANTS.SELECT_TYPE integer
local LOCAL_CONSTANTS = {
	SELECT_TYPE = {
		ALL_BUFF = 0,
		EQUIP_BUFF = 1,
	}
}
--endregion define


--- from: Assets/BundleResources/Prefabs/NightCatInstance/NightCatInstanceBuffDisplayDialog.prefab > name: NightCatInstanceBuffDisplayDialog
---@class MournBuffDisplayDialog
---@field Env                           	MournBuffDisplayDialog
---@field controller                    	Engine.UI.UILuaDialog
---@field TextDesc2                     	UnityEngine.RectTransform               	@ 0    
---@field TextDesc1                     	UnityEngine.RectTransform               	@ 1    
---@field DescScrollView                	UnityEngine.RectTransform               	@ 2
---@field BuffDescNode                  	UnityEngine.RectTransform               	@ 3    
---@field CurrentBuffList               	SuperScrollView.LoopGridView            	@ 4    
---@field AllBuffList                   	Engine.UI.AutoFixSizeListView           	@ 5    
---@field RightPanel                    	UnityEngine.RectTransform               	@ 6    
---@field LeftPanel                     	UnityEngine.RectTransform               	@ 7    
---@field Root                          	UnityEngine.RectTransform               	@ 8    
local MournBuffDisplayDialog = Class("MournBuffDisplayDialog")
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')
local BuffCellPath = "Game.Activity.Mourn.Cell.MournBuffDisplayCell"

function MournBuffDisplayDialog:__init()
	self._activityId = 0
	self._allBuffVos = {}          --所有的buff    
	self._curEquipBuffIds = {}          --当前装备的buff    
	self.curBuffEnv = {}
	self._curAllBuffSelectIndex = 0
	self._curBuffSelectIndex = 0
end

function MournBuffDisplayDialog:__delete()
	self._activityId = 0
	self._allBuffVos = {}          --所有的buff    
	self._curEquipBuffIds = {}          --当前装备的buff    
	self.curBuffEnv = nil
	self._curAllBuffSelectIndex = 0
end

function MournBuffDisplayDialog:OnFocus(focus)
	if focus then
		local currency = ActivityMournUtils.GetShowCurrency()
		if table.count(currency) > 0 then
			CfUtils.RefreshTopGoods(currency)
		end
	end
end

function MournBuffDisplayDialog:Awake()
	local argument = self.controller.Argument.parameters
	if argument then
		self._activityId = checkNumber(argument.activityId)
	end
	
	if checkNumber(self._activityId) == 0 then
		return
	end
	CfUtils.SetActive(self.Cell.gameObject,false)
	self:InitData()
	self:FillSelf()
end

function MournBuffDisplayDialog:InitData()
	local t = ActivityMournUtils.GetTowerItemVos(self._activityId)
	self._allBuffVos = t
	
	self._curEquipBuffIds = ActivityMournUtils.GetEquipBuffIds()
	
	local maxNum = ActivityMournUtils.GetMaxEquipBuffNum()
	if table.count(self._curEquipBuffIds) < maxNum then
		for i = table.count(self._curEquipBuffIds) + 1, maxNum do
			table.insert(self._curEquipBuffIds, 0)
		end
	end
end

function MournBuffDisplayDialog:FillSelf()
	self:FillAllBuff()
	self:FillCurBuff()
end

function MournBuffDisplayDialog:FillAllBuff()
	if self._isInitAllBuffList then
		self.AllBuffList:SetListItemCount(table.count(self._allBuffVos))
	else
		self._isInitAllBuffList = true
		self.AllBuffList:InitListView(table.count(self._allBuffVos), Bind(self, self.OnGetItemByIndex), nil, Bind(self, self.OnGetListItemByIndex))
	end
end

--当前装备的
function MournBuffDisplayDialog:FillCurBuff()
	for i, v in pairs(self._curEquipBuffIds) do
		if self.curBuffEnv[i] then
			self.curBuffEnv[i]:SetCallBack(Bind(self,self.OnBtnSelectEquip))
			self.curBuffEnv[i]:RefreshShow(v,i)
		else
			local go = CfUtils.InstantiateGo(self.Cell.gameObject,self.CurrentBuffList,false)
			if isNotNull(go) then
				local env = CfUtils.GetLuaScr(go, BuffCellPath)
				if isNotNull(env) then
					env:SetCallBack(Bind(self,self.OnBtnSelectEquip))
					env:RefreshShow(v,i)
					CfUtils.SetActive(go.gameObject,true)
					table.insert(self.curBuffEnv,env)
				end
			end
		end
	end
end

---所有的
function MournBuffDisplayDialog:OnGetItemByIndex(go, index, row, column)
	if index < 0 then
		return
	end
	local id = self._allBuffVos[index + 1].id
	self:FillBuffItem(go, id, index + 1, Bind(self,self.OnBtnSelectAll))
end

function MournBuffDisplayDialog:FillBuffItem(go, buffId, index, cb)
	if not go then
		return
	end
	local env = CfUtils.GetLuaScr(go,BuffCellPath)
	if isNotNull(env) then
		env:SetCallBack(cb)
		env:RefreshShow(buffId, index)
		if self._curAllBuffSelectIndex > 0 and self._curAllBuffSelectIndex == index then
			env:SetSelectState(true)
		else
			env:SetSelectState(false)
		end
	end
end

function MournBuffDisplayDialog:OnBtnSelectAll(selectInd, buffId)
	comp:RemoveRedPointList(buffId)
	
	self:CancelSelectIcon()
	self._curAllBuffSelectIndex = checkNumber(selectInd)
	if self._curAllBuffSelectIndex > 0 then
		local go = self.AllBuffList:GetShownItemByItemIndex(checkNumber(self._curAllBuffSelectIndex) - 1)
		if go then
			local env = CfUtils.GetLuaScr(go, BuffCellPath)
			if isNotNull(env) then
				env:SetSelectState(true)
				env:SetImgNewState(false)
				env:PlayAnimatorState("Choose")
			end
		end
	end
	
	self:FillBuffInfo(LOCAL_CONSTANTS.SELECT_TYPE.ALL_BUFF)
end

function MournBuffDisplayDialog:CancelSelectIcon()
	local index = checkNumber(self._curBuffSelectIndex)
	if index > 0 then
		-- 取消已选择的选项
		self.curBuffEnv[self._curBuffSelectIndex]:SetSelectState(false)
	end
	if checkNumber(self._curAllBuffSelectIndex) > 0 then
		local go = self.AllBuffList:GetShownItemByItemIndex(checkNumber(self._curAllBuffSelectIndex) - 1)
		if isNotNull(go) then
			local env = CfUtils.GetLuaScr(go,BuffCellPath)
			if env then
				env:SetSelectState(false)
			end
		end
	end
end

--已装备的直接卸下
function MournBuffDisplayDialog:OnBtnSelectEquip(selectIndex, buffId)
	if checkNumber(buffId) == 0 then
		return
	end
	
	self:CancelSelectIcon()
	self._curBuffSelectIndex = checkNumber(selectIndex)
	local index = checkNumber(self._curBuffSelectIndex)
	if index > 0 then
		self.curBuffEnv[index]:SetSelectState(true)
		self.curBuffEnv[index]:PlayAnimatorState("Choose")
	end
	
	self:FillBuffInfo(LOCAL_CONSTANTS.SELECT_TYPE.EQUIP_BUFF)
	
end

function MournBuffDisplayDialog:OnGetListItemByIndex(go)
end

function MournBuffDisplayDialog:SelectedIndex(type)
	type = checkNumber(type)
	if type == LOCAL_CONSTANTS.SELECT_TYPE.ALL_BUFF then
		return checkNumber(self._curAllBuffSelectIndex)
	elseif type == LOCAL_CONSTANTS.SELECT_TYPE.EQUIP_BUFF then
		return checkNumber(self._curBuffSelectIndex)
	end
	return 0
end

function MournBuffDisplayDialog:BuffId(type, index)
	type = checkNumber(type)
	index = checkInt(index)
	if type == LOCAL_CONSTANTS.SELECT_TYPE.ALL_BUFF then
		return self._allBuffVos[index].id
	elseif type == LOCAL_CONSTANTS.SELECT_TYPE.EQUIP_BUFF then
		return self._curEquipBuffIds[index]
	end
	return 0
end

--buff 信息
---@param type MournBuffDisplayDialog.LOCAL_CONSTANTS.SELECT_TYPE
function MournBuffDisplayDialog:FillBuffInfo(type)
	if checkNumber(self._curAllBuffSelectIndex) < 1 and checkNumber(self._curBuffSelectIndex) < 1 then
		return
	end
	local selectedIndex = self:SelectedIndex(type)
	local buffId = self:BuffId(type, selectedIndex)
	CfUtils.SetActive(self.RightPanel, true)
	local scr = CfUtils.GetLuaScr(self.RightPanel, MournBuffDisplayRightNode)
	if scr then
		scr:Refresh(buffId, function(isEquip)
			if isEquip then
				self._targetBuffId = buffId
			else
				self:CancelSelectIcon()
			end
			self:RefreshInfo(buffId, isEquip)
		end)
	end
end

--刷新数据变化的buff
function MournBuffDisplayDialog:RefreshInfo(buffId, isEquip)
	self:InitData()
	
	self:FillCurBuff()
	
	local ind = checkNumber(table.keyof(self._curEquipBuffIds, checkNumber(buffId)))
	if ind > 0 then
		self.curBuffEnv[ind]:PlayAnimatorState("Assembly")
	end
	
	local index = self:GetIndexByBuffId(buffId)
	self._curAllBuffSelectIndex = index
	local ind = checkNumber(self._curAllBuffSelectIndex)
	if ind > 0 then
		local go = self.AllBuffList:GetShownItemByItemIndex(checkNumber(ind) - 1)
		if isNotNull(go) then
			local env = CfUtils.GetLuaScr(go, BuffCellPath)
			if isNotNull(env) then
				env:RefreshShow(buffId, ind)
			end
		end
	end
end

function MournBuffDisplayDialog:GetIndexByBuffId(buffId)
	for i, v in pairs(self._allBuffVos) do
		if v.id == buffId then
			return i
		end
	end
	return nil
end

function MournBuffDisplayDialog:OnInitialize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		CfUtils.ResetNavigatorCustomBackAction()
	end))
	return coWait
end

function MournBuffDisplayDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
		self:Delete()
		self = nil --lua层的gc需要
	end))
	return coWait
end

return MournBuffDisplayDialog